MM.mnemo[6] = {"cards":[{"id":"ko-k3-0135","w":"보내다","cs":"poslat; strávit (čas)","en":"to send","p":"v","o":"k","ex":"보낼 거예요.","exc":"Pošlu to.","m":"Kromě základního významu ‚poslat‘ (메시지를 보내다 = poslat zprávu) znamená také ‚strávit čas‘ (주말 잘 보내세요 = hezky si užij víkend). Opakem při posílání je 받다 (dostat).","tv":["보내요"]},{"id":"ko-k3-0136","w":"웃다","cs":"smát se; usmívat se","en":"to laugh","p":"v","o":"k","ex":"웃을 거예요.","exc":"Budu se smát.","m":"Pravidelné sloveso na ㅅ: ㅅ zůstává i před samohláskou (웃어요), na rozdíl od nepravidelného 짓다 → 지어요. Opakem je 울다 (plakat).","tv":["웃어요"]},{"id":"ko-k3-0139","w":"도와주다","cs":"pomoci, pomáhat","en":"to help","p":"v","o":"k","ex":"그래요? 제가 도와줄게요.","exc":"Opravdu? Já ti pomůžu. (가 → 1. pád; -ㄹ게요 → slib / ochota)","m":"Vzniklo ze slovesa 돕다 (pomáhat, nepravidelné ㅂ → 도와) a pomocného 주다 (udělat něco pro druhého). Osoba, které pomáháš, má částici 4. pádu 을/를 (친구를 도와주다 = pomoci kamarádovi).","tv":["도와줘요"]},{"id":"ko-k3-0140","w":"주문하다","cs":"objednat, objednávat","en":"to order","p":"v","o":"m","ex":"지금 주문할게요.","exc":"Hned to objednám. (-ㄹ게요 → slib / spontánní rozhodnutí)","m":"注 zapsat, zaměřit + 文 text, zápis (+ 하다) = zapsat požadavek, tedy objednat (jídlo v restauraci nebo zboží přes internet). Podstatné jméno 주문 znamená ‚objednávka‘.","r":["ju-注","mun-文"],"tv":["주문해요"]},{"id":"ko-k3-0142","w":"방","cs":"pokoj, místnost","en":"room","p":"n","o":"s","ex":"방 청소했어요?","exc":"Uklidil jsi pokoj?","m":"房 pokoj, místnost = pokoj. Stejný kořen 房 najdeš na konci slov označujících místnosti pro zábavu či služby, třeba 노래방 (karaoke místnost) nebo PC방 (počítačová herna).","r":["bang-房"]},{"id":"ko-k3-0144","w":"주말","cs":"víkend","en":"weekend","p":"n","o":"s","ex":"주말에 친구들 만날 거예요.","exc":"O víkendu se sejdu s kamarády. (에 → kdy)","m":"週 týden + 末 konec = konec týdne, tedy víkend. Kořen 末 (konec) najdeš i ve slově 연말 (konec roku); opakem víkendu je 평일 (všední den).","r":["ju-週","mal-末"]},{"id":"ko-k3-0145","w":"공원","cs":"park","en":"park","p":"n","o":"s","ex":"공원에 갈 거예요.","exc":"Půjdu do parku. (에 → kam)","m":"公 veřejný + 園 zahrada, sad = veřejná zahrada, tedy park. Stejný kořen 園 najdeš i ve slově 동물원 (zoologická zahrada).","r":["gong-公","won-園"]},{"id":"ko-k3-0146","w":"생일 파티","cs":"narozeninová oslava","en":"birthday party","p":"f","o":"m","ex":"친구 생일 파티에 갈 거예요.","exc":"Půjdu na kamarádovu narozeninovou oslavu. (에 → kam)","m":"生 život, narodit se + 日 den + 파티 (z angl. party) = oslava dne narození, tedy narozeninová oslava. Slovo 생일 (narozeniny) má zdvořilou variantu 생신 pro starší osoby.","r":["saeng-生","il-日"]},{"id":"ko-k3-0147","w":"내년","cs":"příští rok","en":"next year","p":"n","o":"s","ex":"저는 내년에 한국어 공부할 거예요.","exc":"Příští rok se budu učit korejsky. (는 → téma věty; 에 → kdy)","m":"來 přijít + 年 rok = rok, který přijde, tedy příští rok. Srovnej s 올해 (letos) a 작년 (loni); kořen 年 znáš i z výrazů jako 몇 년 (kolik let).","r":["rae-來","nyeon-年"]},{"id":"ko-k3-0148","w":"방해하다","cs":"rušit, vyrušovat; překážet","en":"to disturb","p":"v","o":"m","ex":"방해하지 마세요.","exc":"Nerušte, prosím. (-지 마세요 → záporný rozkaz ‚nedělejte‘)","m":"妨 překážet + 害 škodit (+ 하다) = překážet a škodit někomu v činnosti, tedy rušit. Věta 방해하지 마세요! se používá i jako cedulka ‚Nerušit‘ na hotelových dveřích.","r":["bang-妨","hae-害"]}],"gram":{"id":"ko-k3-g06","w":"-(으)ㄹ 거예요 vs -(으)ㄹ게요","en":"Future Tense","cs":"budu… (plán vs. reakce / slib posluchači)","vy":"Oba vzorce vyjadřují budoucí čas, ale liší se postojem mluvčího. Tvar -(으)ㄹ 거예요 oznamuje pevný plán nebo předpověď nezávislou na posluchači. Tvar -(으)ㄹ게요 se používá pouze v 1. osobě a vyjadřuje spontánní rozhodnutí, slib nebo reakci na to, co řekl druhý (‚tak já to tedy udělám‘).","m":"-(으)ㄹ 거예요 je tvůj vlastní plán ‚ať se děje cokoliv‘, zatímco -(으)ㄹ게요 funguje jako vstřícné gesto směrem k druhému člověku: ‚Tak dobře, udělám to (pro tebe / podle tebe).‘","s":[["공부할 거예요.","Budu se učit. (Můj plán)"],["공부할게요.","Tak já se tedy budu učit."],["방해하지 마세요. 공부할 거예요.","Nerušte mě. Budu se učit."],["알았어요. 공부할게요.","Dobře, budu se učit."],["저도 갈 거예요.","Já půjdu taky. (Měl jsem to v plánu)"],["저도 갈게요.","Tak já půjdu taky (jestli nevadí)."],["지금 어디예요? 지금 나갈게요.","Kde jsi teď? Hned vyjdu ven."],["저 갈게요. 안녕히 계세요.","Já už půjdu. Mějte se hezky."],["그래요? 다시 할게요.","Vážně? Tak já to udělám znovu."],["내일 4시쯤에 갈게요. 괜찮아요?","Přijdu zítra kolem čtvrté, hodí se to?"],["언제 할 거예요? — 지금 할게요.","Kdy to uděláš? — Udělám to hned teď."],["친구들 만날 거예요.","Sejdu se s kamarády."],["내일 전화할게요.","Zítra ti zavolám."],["청소는 제가 할게요.","Úklid udělám já."],["제가 다 먹을게요.","Já to všechno sním."],["그래요? 제가 도와줄게요.","Opravdu? Tak já ti pomůžu."]]}};
